/* ==========================================================================
   EMC Section Row Styling - Print Format Designer
   Customizable directly via Child Table -> Style -> Custom CSS using variables:
     --sec-bg: #eff6ff;
     --sec-border: #bfdbfe;
     --sec-badge-bg: #2563eb;
     --sec-badge-color: #ffffff;
     --sec-title-color: #1e40af;
     --sec-title-size: 14px;
     --sec-badge-display: none; /* to hide badge */
   ========================================================================== */

/* 1. Full Row Highlighting for Section Rows */
tr.table-row:has([data-is-section="1"]),
tr.table-row:has(.emc-print-section-header),
tr.table-row.emc-print-section-row {
    background-color: var(--sec-bg, #f8fafc) !important;
    font-weight: 700 !important;
    -webkit-print-color-adjust: exact !important;
    print-color-adjust: exact !important;
}

tr.table-row:has([data-is-section="1"]) td,
tr.table-row:has(.emc-print-section-header) td,
tr.table-row.emc-print-section-row td {
    background-color: var(--sec-bg, #f8fafc) !important;
    border-top: var(--sec-border-top, var(--sec-border-width, 1.5px) solid var(--sec-border, #cbd5e1)) !important;
    border-bottom: var(--sec-border-bottom, var(--sec-border-width, 1.5px) solid var(--sec-border, #cbd5e1)) !important;
    font-weight: 700 !important;
    -webkit-print-color-adjust: exact !important;
    print-color-adjust: exact !important;
}

/* 2. Hide Unneeded Data Columns on Section Rows */
tr.table-row:has([data-is-section="1"]) td.column-value:not([data-fieldname="item_name"]):not([data-fieldname="section_title"]):not([data-fieldname="idx"]),
tr.table-row:has(.emc-print-section-header) td.column-value:not([data-fieldname="item_name"]):not([data-fieldname="section_title"]):not([data-fieldname="idx"]),
tr.table-row.emc-print-section-row td.column-value:not([data-fieldname="item_name"]):not([data-fieldname="section_title"]):not([data-fieldname="idx"]) {
    display: none !important;
}

/* Optional Toggle: Hide/Show Row Number ('No' column) on Section Rows */
tr.table-row:has([data-is-section="1"]) td.column-value[data-fieldname="idx"],
tr.table-row:has(.emc-print-section-header) td.column-value[data-fieldname="idx"],
tr.table-row.emc-print-section-row td.column-value[data-fieldname="idx"] {
    display: var(--sec-no-display, var(--sec-idx-display, table-cell)) !important;
}

/* 3. Section Title Spans Across the Remaining Table */
tr.table-row:has([data-is-section="1"]) td.column-value[data-fieldname="item_name"],
tr.table-row:has(.emc-print-section-header) td.column-value[data-fieldname="item_name"],
tr.table-row.emc-print-section-row td.column-value[data-fieldname="item_name"] {
    width: var(--sec-title-cell-width, 95%) !important;
    max-width: none !important;
}

/* 4. Section Header Container & Typography */
.emc-print-section-header {
    display: flex !important;
    align-items: center !important;
    justify-content: space-between !important;
    width: 100% !important;
    box-sizing: border-box !important;
    gap: 12px !important;
    padding: 2px 0 !important;
}

.emc-print-section-main {
    display: inline-flex !important;
    align-items: center !important;
    gap: 8px !important;
    flex-wrap: wrap !important;
}

.emc-print-section-badge {
    background-color: var(--sec-badge-bg, #0f172a) !important;
    color: var(--sec-badge-color, #ffffff) !important;
    font-size: var(--sec-badge-size, 8.5px) !important;
    font-weight: 700 !important;
    padding: 2px 7px !important;
    border-radius: var(--sec-badge-radius, 4px) !important;
    letter-spacing: 0.05em !important;
    text-transform: uppercase !important;
    display: var(--sec-badge-display, inline-block) !important;
    flex-shrink: 0 !important;
    white-space: nowrap !important;
    -webkit-print-color-adjust: exact !important;
    print-color-adjust: exact !important;
}

.emc-print-section-title {
    font-size: var(--sec-title-size, 13.5px) !important;
    font-weight: var(--sec-title-weight, 700) !important;
    color: var(--sec-title-color, #0f172a) !important;
    letter-spacing: 0.01em !important;
    display: inline-block !important;
}

.emc-print-section-total {
    display: var(--sec-total-display, inline-flex) !important;
    align-items: center !important;
    gap: 5px !important;
    font-size: var(--sec-total-size, 12.5px) !important;
    font-weight: var(--sec-total-weight, 600) !important;
    color: var(--sec-total-color, var(--sec-title-color, #0f172a)) !important;
    background-color: var(--sec-total-bg, transparent) !important;
    padding: var(--sec-total-padding, 0) !important;
    border-radius: var(--sec-total-radius, 4px) !important;
    white-space: nowrap !important;
    margin-left: auto !important;
    -webkit-print-color-adjust: exact !important;
    print-color-adjust: exact !important;
}

.emc-print-section-total-label {
    display: var(--sec-total-label-display, inline) !important;
    font-size: 0.9em !important;
    opacity: 0.8 !important;
    font-weight: 500 !important;
}

.emc-print-section-total-amount {
    font-weight: var(--sec-total-weight, 600) !important;
    font-variant-numeric: tabular-nums !important;
}

/* 5. Hide empty description line in merged item cell for sections */
tr.table-row:has([data-is-section="1"]) .cell-line--muted-sm,
tr.table-row.emc-print-section-row .cell-line--muted-sm {
    display: none !important;
}

/* 6. Section Subtotal Rows (when sec-total-position: bottom) */
tr.table-row:has([data-is-section-subtotal="1"]),
tr.table-row.emc-print-section-subtotal-row {
    display: var(--sec-subtotal-display, table-row) !important;
    background-color: var(--sec-subtotal-bg, #f8fafc) !important;
    font-weight: 700 !important;
    -webkit-print-color-adjust: exact !important;
    print-color-adjust: exact !important;
}

tr.table-row:has([data-is-section-subtotal="1"]) td,
tr.table-row.emc-print-section-subtotal-row td {
    background-color: var(--sec-subtotal-bg, #f8fafc) !important;
    border-top: var(--sec-subtotal-border-top, 1.5px solid var(--sec-subtotal-border, #cbd5e1)) !important;
    border-bottom: var(--sec-subtotal-border-bottom, 2px solid var(--sec-title-color, #0f172a)) !important;
    padding-top: 7px !important;
    padding-bottom: 7px !important;
    font-weight: 700 !important;
    vertical-align: middle !important;
    -webkit-print-color-adjust: exact !important;
    print-color-adjust: exact !important;
}

tr.table-row:has([data-is-section-subtotal="1"]) td.column-value[data-fieldname="amount"],
tr.table-row.emc-print-section-subtotal-row td.column-value[data-fieldname="amount"] {
    text-align: right !important;
}

.emc-print-subtotal-cell {
    display: inline-flex !important;
    align-items: center !important;
    gap: 8px !important;
    line-height: 1.3 !important;
}

.emc-print-subtotal-badge {
    background-color: var(--sec-subtotal-badge-bg, var(--sec-badge-bg, #0f172a)) !important;
    color: var(--sec-subtotal-badge-color, var(--sec-badge-color, #ffffff)) !important;
    font-size: 8px !important;
    font-weight: 700 !important;
    letter-spacing: 0.05em !important;
    padding: 2px 6px !important;
    border-radius: 4px !important;
    text-transform: uppercase !important;
    display: var(--sec-subtotal-badge-display, inline-block) !important;
    flex-shrink: 0 !important;
    white-space: nowrap !important;
    -webkit-print-color-adjust: exact !important;
    print-color-adjust: exact !important;
}

.emc-print-subtotal-title {
    font-size: var(--sec-subtotal-size, 13px) !important;
    font-weight: var(--sec-subtotal-weight, 700) !important;
    color: var(--sec-subtotal-color, var(--sec-title-color, #0f172a)) !important;
    letter-spacing: 0.01em !important;
    white-space: nowrap !important;
}

.emc-print-subtotal-amount {
    font-size: 13.5px !important;
    font-weight: 800 !important;
    font-variant-numeric: tabular-nums !important;
    color: var(--sec-subtotal-color, var(--sec-title-color, #0f172a)) !important;
    text-align: right !important;
    display: block !important;
    width: 100% !important;
    white-space: nowrap !important;
}

